280→        for (var i = 0; i < arguments.Length; i++)
281→        {
282→            var arg = arguments[i];
283→
284→            switch (arg)
285→            {
286→                case "--project":
287→                    options.Project = GetValue(arguments, ref i);
288→                    break;
289→                case "--out-dir":
290→                    options.OutputDirectory = Path.GetFullPath(GetValue(arguments, ref i));
291→                    break;
292→                case "--configuration":
293→                    options.Configuration = GetValue(arguments, ref i);
294→                    break;
295→                case "--force":
296→                case "-f":
297→                    options.Force = true;
298→                    break;
299→                case "--verbose":
