359→static class ChecksumCollector
360→{
361→    public static Dictionary<string, string> Collect(string projectDir)
362→    {
363→        var checksums = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
364→
365→        var nativeDir = Path.Combine(projectDir, "native");
366→        var codegenDir = Path.Combine(projectDir, "codegen");
367→
368→        AddFile(checksums, Path.Combine(nativeDir, "Cargo.toml"), Path.Combine("native", "Cargo.toml"));
369→        AddFile(checksums, Path.Combine(codegenDir, "Cargo.toml"), Path.Combine("codegen", "Cargo.toml"));
370→
371→        AddDirectory(checksums, Path.Combine(nativeDir, "src"), "native/src");
372→        AddDirectory(checksums, Path.Combine(codegenDir, "src"), "codegen/src");
373→
374→        return checksums;
375→    }
376→
377→    public static bool HasDifferences(
378→        Dictionary<string, string> previous,
379→        Dictionary<string, string> current,
380→        string prefix)
381→    {
382→        foreach (var kvp in current)
383→        {
384→            if (!kvp.Key.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
385→            {
386→                continue;
387→            }
388→
389→            if (!previous.TryGetValue(kvp.Key, out var oldChecksum) || !oldChecksum.Equals(kvp.Value, StringComparison.OrdinalIgnoreCase))
390→            {
391→                return true;
392→            }
393→        }
394→
395→        foreach (var kvp in previous)
396→        {
397→            if (!kvp.Key.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
398→            {
399→                continue;
400→            }
401→
402→            if (!current.ContainsKey(kvp.Key))
403→            {
404→                return true;
405→            }
406→        }
407→
408→        return false;
409→    }
410→
411→    private static void AddDirectory(Dictionary<string, string> checksums, string directory, string prefix)
412→    {
413→        if (!Directory.Exists(directory))
414→        {
415→            return;
416→        }
417→
418→        foreach (var file in Directory.EnumerateFiles(directory, "*.*", SearchOption.AllDirectories))
419→        {
420→            if (!file.EndsWith(".rs", StringComparison.OrdinalIgnoreCase))
421→            {
422→                continue;
423→            }
424→
425→            var relative = Path.GetRelativePath(directory, file).Replace('\\', '/');
426→            var key = $"{prefix}/{relative}";
427→            checksums[key] = ComputeChecksum(file);
428→        }
429→    }
430→
431→    private static void AddFile(Dictionary<string, string> checksums, string path, string key)
432→    {
433→        if (File.Exists(path))
434→        {
435→            checksums[key] = ComputeChecksum(path);
436→        }
437→    }
438→
439→    private static string ComputeChecksum(string file)
440→    {
441→        using var stream = File.OpenRead(file);
442→        using var sha256 = SHA256.Create();
443→        var hash = sha256.ComputeHash(stream);
444→        return Convert.ToHexString(hash);
445→    }
446→}
